INSERT INTO `proposal_draft_documents` VALUES (1,1,'detailed_proposal',0,'{\"sdgs\": [13, 14, 17], \"staff\": [], \"rationale\": \"Coastal habitat degradation threatens biodiversity and local livelihoods.\", \"references\": \"Synthetic Author, A. (2025). Coastal habitat restoration. Synthetic Journal, 1(1), 1-10.\", \"methodology\": {\"data_analysis\": \"Data will be analyzed with descriptive statistics and thematic analysis.\", \"research_design\": \"The project uses a mixed-method design.\", \"specific_methods\": \"The team will conduct surveys, transects, and stakeholder workshops.\"}, \"introduction\": \"The project responds to coastal habitat degradation through community research.\", \"leader_email\": \"capacity-faculty@example.test\", \"project_title\": \"Capacity Coastal Habitat Restoration\", \"leader_contact\": \"09171234567\", \"project_leader\": \"Capacity Faculty\", \"executive_brief\": \"This project restores priority coastal habitats through evidence-based community action.\", \"research_agenda\": \"Environment and Climate Change\", \"approved_by_name\": \"Capacity Signatory\", \"expected_outputs\": {\"patent\": [], \"policy\": [{\"description\": \"Restoration protocol\"}], \"product\": [{\"description\": \"Validated restoration model\"}], \"publication\": [{\"description\": \"One peer-reviewed publication\"}], \"social_impact\": [{\"description\": \"Improved participation\"}], \"people_service\": [{\"description\": \"Community training\"}], \"economic_impact\": [{\"description\": \"Protected livelihoods\"}], \"place_partnership\": [{\"description\": \"University-LGU partnership\"}]}, \"proponent_campus\": \"ARASOF-Nasugbu\", \"responsibilities\": [{\"name\": \"Capacity Faculty\", \"duties\": \"Leads implementation, quality assurance, and reporting.\", \"percentage\": 100}], \"general_objective\": \"Document baseline conditions and validate a community restoration model.\", \"proponent_college\": \"College of Informatics and Computing Sciences\", \"co